-- A jsonb GIN index holds a 3 000-character string value, and the containment probe
-- finds it; 18.6's `jsonb_ops` hashes a long key or value, so none is ever too large.
-- @setup
CREATE TABLE g (j jsonb);
CREATE INDEX g_i ON g USING gin (j);
INSERT INTO g VALUES ('{"k": ""}');
-- @test
-- @profile-lock
SELECT count(*) FROM g WHERE j @> '{"k": ""}';
